package com.ruoyi.web.controller.shop;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import java.util.*;import static com.ruoyi.web.controller.shop.ShopService.*;
@Component public class ShopMarketingJobs {
 @Autowired ShopMarketing m;@Autowired ShopService s;private final Logger log=LoggerFactory.getLogger(getClass());
 @Scheduled(fixedDelay=30000,initialDelay=30000) public void sweep(){for(Map<String,Object> c:s.jdbc().queryForList("select id from shop_campaign where status='active' and ends_at<=now() limit 100"))try{m.close(number(c.get("id")),"系统");}catch(Exception e){log.warn("活动结束处理失败 id={}",c.get("id"));}for(Map<String,Object> g:s.jdbc().queryForList("select id from shop_campaign_group where status='open' and expires_at<=now() limit 100"))try{m.failGroup(number(g.get("id")));}catch(Exception e){log.warn("拼团超时处理失败 id={}",g.get("id"));}for(Map<String,Object> o:s.jdbc().queryForList("select c.order_id from shop_campaign_order c join shop_campaign_group g on g.id=c.group_id join shop_order o on o.id=c.order_id where g.status='failed' and o.status in ('pending','paid') limit 100"))try{m.refundFailed(number(o.get("order_id")));}catch(Exception e){log.warn("拼团退款等待重试 order={}",o.get("order_id"));}}
}
